    vowels = 'aeiouAEIOU'
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = []

    for char in message:
        if char.isalpha():
            # Swap the case
            is_upper = char.isupper()
            base_char = char.lower()

            # Check if it's a vowel
            if base_char in 'aeiou':
                # Find the index in the alphabet
                idx = alphabet.find(base_char)
                # Move 2 places ahead (circularly)
                new_char = alphabet[(idx + 2) % 26]
                # Apply the swapped case
                if is_upper:
                    result.append(new_char.upper())
                else:
                    result.append(new_char.lower())
            else:
                # Not a vowel, just swap case
                new_char = base_char
                if is_upper:
                    result.append(new_char.upper())
                else:
                    result.append(new_char.lower())
        else:
            # Non-alphabetic characters (spaces, etc.) remain unchanged
            result.append(char)

    return "".join(result)

